    fractional = d - Decimal(integer_part)

    if fractional == Decimal("0.5"):
        if mode == "even":
            return integer_part if integer_part % 2 == 0 else integer_part + 1
        else:  # mode == "up"
            return integer_part + 1

    if fractional == Decimal("-0.5"):
        # Not reachable for non-negative amounts, but kept for completeness.
        if mode == "even":
