from decimal import Decimal


class InsufficientFunds(Exception):
    pass


class Ledger:
    _amount_re = re.compile(r'^\d+(\.\d{1,2})?$')

    def __init__(self, overdraft_limit='0.00'):
        self._validate_format(overdraft_limit, allow_zero=True)
        self._overdraft_limit = Decimal(overdraft_limit)
        self._balance = Decimal('0.00')
        self._history = []

    @staticmethod
    def _validate_format(amount, allow_zero=False):
        if not isinstance(amount, str):
            raise TypeError("amount must be a string")
        if not Ledger._amount_re.match(amount):
            raise ValueError("invalid amount format")
        if not allow_zero and Decimal(amount) == 0:
            raise ValueError("amount must be non-zero")

    def deposit(self, amount):
        self._validate_format(amount, allow_zero=False)
        dec_amount = Decimal(amount)
        self._balance += dec_amount
        self._history.append(('deposit', f'{dec_amount:.2f}'))

    def withdraw(self, amount):
        self._validate_format(amount, allow_zero=False)
        dec_amount = Decimal(amount)
        tentative_balance = self._balance - dec_amount
        if tentative_balance < -self._overdraft_limit:
            raise InsufficientFunds("withdrawal would exceed overdraft limit")
        self._balance = tentative_balance
        self._history.append(('withdraw', f'{dec_amount:.2f}'))
        if self._balance < 0:
            fee = Decimal('1.50')
            self._balance -= fee
            self._history.append(('fee', f'{fee:.2f}'))

    def balance(self):
        return f'{self._balance:.2f}'

    def history(self):
        return list(self._history)
