import heapq
from typing import Sequence


def _validate_and_prepare(meetings: list[tuple[int, int]], k: int):
    if not isinstance(k, int) or isinstance(k, bool):
        raise ValueError("k must be an int and not a bool")
    if k < 1:
        raise ValueError("k must be >= 1")

    if not isinstance(meetings, list):
        raise ValueError("meetings must be a list")

    indexed_meetings = []
    for idx, meeting in enumerate(meetings):
        if not isinstance(meeting, Sequence) or isinstance(meeting, (str, bytes)):
            raise ValueError("each meeting must be a length-2 sequence")
        if len(meeting) != 2:
            raise ValueError("each meeting must be a length-2 sequence")
        start, end = meeting
        if not isinstance(start, int) or isinstance(start, bool):
            raise ValueError("start must be an int and not a bool or float")
        if not isinstance(end, int) or isinstance(end, bool):
            raise ValueError("end must be an int and not a bool or float")
        if start >= end:
            raise ValueError("start must be less than end")
        indexed_meetings.append((start, idx, end))

    return indexed_meetings, k


def _assign(meetings: list[tuple[int, int]], k: int):
    indexed_meetings, k = _validate_and_prepare(meetings, k)

    n = len(indexed_meetings)
    result = [None] * n
    if n == 0:
        return result, []

    indexed_meetings.sort(key=lambda x: (x[0], x[1]))

    available = list(range(k))
    heapq.heapify(available)
    occupied = []  # min-heap of (release_time, room_id)
    usage = [0] * k

    for start, original_idx, end in indexed_meetings:
        # Release all rooms that are free at or before start
        while occupied and occupied[0][0] <= start:
            release_time, room_id = heapq.heappop(occupied)
            heapq.heappush(available, room_id)

        if available:
            actual_start = start
            room_id = heapq.heappop(available)
        else:
            earliest_release = occupied[0][0]
            # Release all rooms with this earliest release time
            while occupied and occupied[0][0] == earliest_release:
                release_time, room_id = heapq.heappop(occupied)
                heapq.heappush(available, room_id)
            actual_start = earliest_release
            room_id = heapq.heappop(available)

        duration = end - start
        actual_end = actual_start + duration
        result[original_idx] = (room_id, actual_start, actual_end)
        usage[room_id] += 1
        heapq.heappush(occupied, (actual_end, room_id))

    return result, usage


def assign_rooms(meetings: list[tuple[int, int]], k: int) -> list[tuple[int, int, int]]:
    result, _ = _assign(meetings, k)
    return result


def busiest_room(meetings: list[tuple[int, int]], k: int) -> int:
    _, usage = _assign(meetings, k)
    if not usage or all(u == 0 for u in usage):
        return 0
    max_usage = max(usage)
    return usage.index(max_usage)
