    if isinstance(limit, bool):
        raise ValueError("limit must not be a bool")
    if not isinstance(limit, (int, float)):
        raise ValueError("limit must be an int or float")
    if math.isnan(limit):
        raise ValueError("limit must not be NaN")
    if limit < 0:
        raise ValueError("limit must be non-negative")


def _validate_element(value) -> None:
    if isinstance(value, bool):
        raise TypeError("values must contain only int or float, not bool")
    if not isinstance(value, (int, float)):
        raise TypeError("values must contain only int or float")
    if isinstance(value, float) and math.isnan(value):
        raise ValueError("values must not contain NaN")


def _validate_values(values: List[Number]) -> None:
    for v in values:
        _validate_element(v)


def longest_calm(values: List[Number], limit: Number) -> tuple[int, int]:
    _validate_limit(limit)

    if not values:
        return (0, 0)

    _validate_values(values)

    max_deque = collections.deque()
    min_deque = collections.deque()
    left = 0
    best_left = 0
    best_len = 1

    for right, value in enumerate(values):
        while max_deque and values[max_deque[-1]] <= value:
            max_deque.pop()
        while min_deque and values[min_deque[-1]] >= value:
            min_deque.pop()
        max_deque.append(right)
        min_deque.append(right)

        while max_deque and min_deque and values[max_deque[0]] - values[min_deque[0]] > limit:
            if max_deque[0] == left:
                max_deque.popleft()
            if min_deque[0] == left:
                min_deque.popleft()
            left += 1

        window_len = right - left + 1
        if window_len > best_len:
            best_len = window_len
            best_left = left

    return (best_left, best_left + best_len)


def count_calm(values: List[Number], limit: Number) -> int:
    _validate_limit(limit)

    if not values:
        return 0

    _validate_values(values)

    max_deque = collections.deque()
    min_deque = collections.deque()
    left = 0
    total = 0

    for right, value in enumerate(values):
        while max_deque and values[max_deque[-1]] <= value:
            max_deque.pop()
        while min_deque and values[min_deque[-1]] >= value:
