class CycleError(ValueError):
    def __init__(self, nodes):
        self.nodes = list(nodes)
        super().__init__(f"cycle detected involving nodes: {self.nodes}")


def _build_graph(nodes, edges):
    node_set = set(nodes)
    for before, after in edges:
        if before not in node_set:
            raise ValueError(f"unknown node: {before}")
        if after not in node_set:
            raise ValueError(f"unknown node: {after}")

    successors = {node: [] for node in node_set}
    in_degree = {node: 0 for node in node_set}
    seen_edges = set()
    for before, after in edges:
        if before == after:
            continue
        edge = (before, after)
        if edge in seen_edges:
            continue
        seen_edges.add(edge)
        successors[before].append(after)
        in_degree[after] += 1

    return node_set, successors, in_degree


def topo_order(nodes, edges):
    node_set, successors, in_degree = _build_graph(nodes, edges)

    remaining = set(node_set)
    result = []
    while remaining:
        sources = [node for node in remaining if in_degree[node] == 0]
        if not sources:
            raise CycleError(sorted(remaining))
        source = min(sources)
        result.append(source)
        remaining.remove(source)
        for succ in successors[source]:
            in_degree[succ] -= 1

    return result


def layers(nodes, edges):
    node_set, successors, in_degree = _build_graph(nodes, edges)

    remaining = set(node_set)
    result = []
    while remaining:
        sources = [node for node in remaining if in_degree[node] == 0]
        if not sources:
            raise CycleError(sorted(remaining))
        layer = sorted(sources)
        result.append(layer)
        for source in layer:
            remaining.remove(source)
            for succ in successors[source]:
                in_degree[succ] -= 1

    return result
