def _normalize(intervals):
    normalized = []
    for iv in intervals:
        if len(iv) != 2:
            raise ValueError("Each interval must be a 2-item sequence")
        start, end = iv
        if start > end:
            raise ValueError("Interval start cannot be greater than end")
        if start == end:
            continue
        normalized.append((start, end))
    return normalized


def merge(intervals):
    intervals = _normalize(intervals)
    if not intervals:
        return []
    intervals = sorted(intervals, key=lambda x: x[0])
    merged = [intervals[0]]
    for start, end in intervals[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged


def subtract(a, b):
    a = merge(a)
    b = merge(b)
    result = []
    i = 0
    for start, end in a:
        current_start = start
        while i < len(b) and b[i][1] <= current_start:
            i += 1
        while i < len(b) and b[i][0] < end:
            b_start, b_end = b[i]
            if b_start > current_start:
                result.append((current_start, b_start))
            current_start = max(current_start, b_end)
            if current_start >= end:
                break
            if b_end <= end:
                i += 1
            else:
                break
        if current_start < end:
            result.append((current_start, end))
    return result


def total_length(intervals):
    merged = merge(intervals)
    return sum(end - start for start, end in merged)
