from fractions import Fraction

def evaluate(expr):
    s = expr
    n = len(s)
    pos = 0

    def peek():
        nonlocal pos
        while pos < n and s[pos] in ' \t':
            pos += 1
        if pos < n:
            return s[pos]
        return None

    def consume(expected=None):
        nonlocal pos
        c = peek()
        if c is None:
            return None
        if expected is not None and c != expected:
            return None
        pos += 1
        return c

    def parse_expr():
        value = parse_term()
        while True:
            c = peek()
            if c == '+' or c == '-':
                consume(c)
                rhs = parse_term()
                if c == '+':
                    value = value + rhs
                else:
                    value = value - rhs
            else:
                break
        return value

    def parse_term():
        value = parse_unary()
        while True:
            c = peek()
            if c == '*' or c == '/':
                consume(c)
                rhs = parse_unary()
                if c == '*':
                    value = value * rhs
                else:
                    value = value / rhs
            else:
                break
        return value

    def parse_unary():
        c = peek()
        if c == '-':
            consume('-')
            return -parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        c = peek()
        if c == '^':
            consume('^')
            exp = parse_unary()
            return power(base, exp)
        return base

    def parse_atom():
        c = peek()
        if c == '(':
            consume('(')
            value = parse_expr()
            if peek() != ')':
                raise ValueError("missing closing parenthesis")
            consume(')')
            return value
        if c is not None and c.isdigit():
            start = pos
            while pos < n and s[pos].isdigit():
                pos += 1
            return Fraction(int(s[start:pos]))
        raise ValueError("expected number or '('")

    def power(base, exp):
        if exp.denominator != 1:
            raise ValueError("exponent must be a whole number")
        e = exp.numerator
        if base == 0:
            if e < 0:
                raise ZeroDivisionError("0 cannot be raised to a negative power")
            if e == 0:
                return Fraction(1)
            return Fraction(0)
        if e < 0:
            return Fraction(1) / (base ** (-e))
        return base ** e

    if not isinstance(expr, str):
        raise ValueError("input must be a string")
    if expr == "":
        raise ValueError("empty input")

    result = parse_expr()
    if peek() is not None:
        raise ValueError("leftover tokens")

    if result.denominator == 1:
        return result.numerator
    return result
