def spans(prices: list) -> list:
    result = []
    stack = []
    for i, p in enumerate(prices):
        if p is None:
            result.append(0)
            stack.append(i)
        else:
            if isinstance(p, bool) or not isinstance(p, (int, float)):
                raise TypeError(f"price at index {i} must be int, float, or None, got {type(p).__name__}")
            while stack and prices[stack[-1]] is not None and prices[stack[-1]] <= p:
                stack.pop()
            if stack:
                span = i - stack[-1]
            else:
                span = i + 1
            result.append(span)
            stack.append(i)
    return result


def next_greater(prices: list) -> list:
    result = [-1] * len(prices)
    pending = []
    for j, p in enumerate(prices):
        if p is None:
            for idx in pending:
                result[idx] = -1
            pending.clear()
            result[j] = -1
        else:
            if isinstance(p, bool) or not isinstance(p, (int, float)):
                raise TypeError(f"price at index {j} must be int, float, or None, got {type(p).__name__}")
            while pending and prices[pending[-1]] < p:
                result[pending.pop()] = j
            pending.append(j)
    for idx in pending:
        result[idx] = -1
    return result


def widest_span(prices: list) -> tuple:
    span_list = spans(prices)
    best_index = -1
    best_span = 0
    for i, s in enumerate(span_list):
        if s >= best_span:
            best_index = i
            best_span = s
    return (best_index, best_span)
