def expand_field(field, lo, hi):
    if not field or not field.strip():
        raise ValueError("invalid cron: empty field")

    values = set()
    for item in field.split(","):
        if not item:
            raise ValueError("invalid cron: empty item")

        base, step_str = item, None
        if "/" in item:
            if item.count("/") != 1:
                raise ValueError("invalid cron: malformed step")
            base, step_str = item.split("/")
            if not step_str or not step_str.isdigit():
                raise ValueError("invalid cron: invalid step")
            step = int(step_str)
            if step == 0:
                raise ValueError("invalid cron: step must be >= 1")
        else:
            step = 1

        if base == "":
            raise ValueError("invalid cron: empty base")

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            if base.count("-") != 1:
                raise ValueError("invalid cron: malformed range")
            a_str, b_str = base.split("-")
            if not a_str or not a_str.isdigit() or not b_str or not b_str.isdigit():
                raise ValueError("invalid cron: invalid range")
            start, end = int(a_str), int(b_str)
            if start > end:
                raise ValueError("invalid cron: range start greater than end")
        elif base.isdigit():
            start = int(base)
            end = hi
        else:
            raise ValueError("invalid cron: invalid item")

        if not (lo <= start <= hi):
            raise ValueError("invalid cron: value out of range")
        if not (lo <= end <= hi):
            raise ValueError("invalid cron: value out of range")

        for v in range(start, end + 1, step):
            if not (lo <= v <= hi):
                raise ValueError("invalid cron: generated value out of range")
            values.add(v)

    return sorted(values)


def _expand_expression(expr):
    if expr is None or not expr.strip():
        raise ValueError("invalid cron: empty expression")

    parts = expr.strip().split()
    if len(parts) != 2:
        raise ValueError("invalid cron: expression must have exactly two fields")

    minute_field, hour_field = parts
    minutes = expand_field(minute_field, 0, 59)
    hours = expand_field(hour_field, 0, 23)
    return minutes, hours


def cron_matches(expr, hour, minute):
    minutes, hours = _expand_expression(expr)
    return hour in hours and minute in minutes


def next_match(expr, hour, minute):
    minutes, hours = _expand_expression(expr)

    if not minutes or not hours:
        raise ValueError("invalid cron: no matching times")

    # Same hour, later minute
    if hour in hours:
        later_minutes = [m for m in minutes if m > minute]
        if later_minutes:
            return (hour, later_minutes[0])

    # Later hours today
    later_hours = [h for h in hours if h > hour]
    for h in later_hours:
        return (h, minutes[0])

    # Wrap to next day: earliest matching hour and minute
    return (hours[0], minutes[0])
