from typing import Iterable, Optional


class Scheduler:
    def __init__(self) -> None:
        self._tasks: dict[str, dict] = {}
        self._insertion_counter = 0

    def add(self, name: str, priority: int, after: Iterable[str] = ()) -> None:
        if name in self._tasks:
            raise ValueError(f"Task {name!r} already added")
        after_set = set(after)
        unknown = after_set - self._tasks.keys()
        if unknown:
            raise KeyError(f"Unknown dependency: {unknown.pop()}")
        self._tasks[name] = {
            "priority": priority,
            "after": after_set,
            "status": "pending",
            "insertion_index": self._insertion_counter,
        }
        self._insertion_counter += 1

    def next(self) -> Optional[str]:
        completed_names = {
            name for name, meta in self._tasks.items() if meta["status"] == "completed"
        }
        ready = [
            (name, meta)
            for name, meta in self._tasks.items()
            if meta["status"] == "pending" and meta["after"].issubset(completed_names)
        ]
        if not ready:
            return None
        name, meta = max(
            ready,
            key=lambda item: (item[1]["priority"], -item[1]["insertion_index"]),
        )
        meta["status"] = "running"
        return name

    def complete(self, name: str) -> None:
        if name not in self._tasks:
            raise KeyError(f"Unknown task: {name!r}")
        meta = self._tasks[name]
        if meta["status"] != "running":
            raise ValueError(f"Task {name!r} is not running")
        meta["status"] = "completed"

    def remaining(self) -> int:
        return sum(1 for meta in self._tasks.values() if meta["status"] != "completed")
