import bisect


def _validate(intervals):
    if not isinstance(intervals, list):
        raise TypeError("intervals must be a list")
    for interval in intervals:
        if not isinstance(interval, tuple) or len(interval) != 3:
            raise TypeError("each interval must be a tuple of 3 integers")
        start, end, weight = interval
        if type(start) is not int or type(end) is not int or type(weight) is not int:
            raise TypeError("start, end, and weight must be int")
        if start >= end:
            raise ValueError("start must be less than end")


def best_schedule(intervals: list[tuple[int, int, int]]) -> tuple[int, int]:
    _validate(intervals)

    sorted_intervals = sorted(intervals, key=lambda x: x[1])
    ends = [end for _, end, _ in sorted_intervals]

    # dp[i] = (max total weight, negative interval count) using first i intervals
    dp = [(0, 0)]
    for start, end, weight in sorted_intervals:
        p = bisect.bisect_right(ends, start)
        # include: dp[p] + (weight, -1)
        include_weight = dp[p][0] + weight
        include_count = dp[p][1] - 1
        # skip: dp[-1]
        skip = dp[-1]
        include = (include_weight, include_count)
        # choose lexicographically larger: higher weight, then fewer intervals (more negative count)
        if include > skip:
            dp.append(include)
        else:
            dp.append(skip)

    total_weight, neg_count = dp[-1]
    if total_weight <= 0:
        return (0, 0)
    return (total_weight, -neg_count)


def max_parallel(intervals: list[tuple[int, int, int]]) -> int:
    _validate(intervals)

    events = []
    for start, end, _ in intervals:
        events.append((start, 1))
        events.append((end, -1))

    # Sort by time; at same time, end events (-1) come before start events (+1)
    events.sort(key=lambda x: (x[0], x[1]))

    current = 0
    max_count = 0
    for _, delta in events:
        current += delta
        if current > max_count:
            max_count = current

    return max_count
