def render(template: str, values: dict) -> str:
    out = []
    n = len(template)
    i = 0
    literal_start = 0

    def flush_literal(end):
        if end > literal_start:
            out.append(template[literal_start:end])

    while i < n:
        ch = template[i]
        if ch == '\\':
            flush_literal(i)
            if i + 2 < n and template[i + 1] == '{' and template[i + 2] == '{':
                out.append('{{')
                i += 3
                literal_start = i
                continue
            elif i + 1 < n and template[i + 1] == '\\':
                out.append('\\')
                i += 2
                literal_start = i
                continue
            else:
                out.append('\\')
                i += 1
                literal_start = i
                continue
        elif ch == '{' and i + 1 < n and template[i + 1] == '{':
            start = i
            flush_literal(i)
            close = template.find('}}', i + 2)
            if close == -1:
                raise ValueError(f"unclosed placeholder at {start}")
            body = template[i + 2:close]
            pipe = body.find('|')
            if pipe == -1:
                key_part = body
                default_part = None
            else:
                key_part = body[:pipe]
                default_part = body[pipe + 1:]
            key = key_part.strip(' ')
            if default_part is None:
                default = None
            else:
                default = default_part.strip(' ')

            # validate key
            segments = key.split('.')
            for seg in segments:
                if not seg:
                    raise ValueError(f"bad key: {key}")
                if not (seg[0].isalpha() or seg[0] == '_'):
                    raise ValueError(f"bad key: {key}")
                for c in seg[1:]:
                    if not (c.isalnum() or c == '_'):
                        raise ValueError(f"bad key: {key}")

            # resolve key
            missing = False
            cur = values
            for seg in segments:
                if not isinstance(cur, dict) or seg not in cur:
                    missing = True
                    break
                cur = cur[seg]
            if not missing and cur is None:
                missing = True

            if missing:
                if default is not None:
                    out.append(default)
                else:
                    raise KeyError(f"missing: {key}")
            else:
                if cur is True:
                    out.append('true')
                elif cur is False:
                    out.append('false')
                else:
                    out.append(str(cur))

            i = close + 2
            literal_start = i
            continue
        else:
            i += 1

    flush_literal(n)
    return "".join(out)
