import re
from typing import Optional, Union

_VERSION_RE = re.compile(
    r'''
    ^(?i:v)?                          # optional leading v/V
    (?P<major>0|[1-9]\d*)\.
    (?P<minor>0|[1-9]\d*)\.
    (?P<patch>0|[1-9]\d*)
    (?:
        -(?P<prerelease>
            (?:0|[1-9]\d*|[A-Za-z-][A-Za-z0-9-]*)
            (?:\.(?:0|[1-9]\d*|[A-Za-z-][A-Za-z0-9-]*))*
        )
    )?
    (?:
        \+(?P<build>
            [A-Za-z0-9-]+
            (?:\.[A-Za-z0-9-]+)*
        )
    )?
    $
    ''',
    re.VERBOSE,
)


def parse_version(text: str) -> tuple[int, int, int, tuple[Union[int, str], ...], Optional[str]]:
    match = _VERSION_RE.match(text)
    if not match:
        raise ValueError(f"invalid version: {text!r}")

    major = int(match.group("major"))
    minor = int(match.group("minor"))
    patch = int(match.group("patch"))

    prerelease_raw = match.group("prerelease")
    if prerelease_raw is None:
        prerelease: tuple[Union[int, str], ...] = ()
    else:
        parsed_prerelease: list[Union[int, str]] = []
        for ident in prerelease_raw.split("."):
            if ident.isdigit():
                if len(ident) > 1 and ident[0] == "0":
                    raise ValueError(f"invalid version: {text!r}")
                parsed_prerelease.append(int(ident))
            else:
                parsed_prerelease.append(ident)
        prerelease = tuple(parsed_prerelease)

    build = match.group("build")

    return (major, minor, patch, prerelease, build)


def _prerelease_key(prerelease: tuple[Union[int, str], ...]) -> tuple:
    return tuple(
        (0, ident) if isinstance(ident, int) else (1, ident)
        for ident in prerelease
    )


def compare_versions(a: str, b: str) -> int:
    a_parsed = parse_version(a)
    b_parsed = parse_version(b)

    for key in (0, 1, 2):
        if a_parsed[key] < b_parsed[key]:
            return -1
        if a_parsed[key] > b_parsed[key]:
            return 1

    a_pre = a_parsed[3]
    b_pre = b_parsed[3]

    if a_pre == b_pre:
        return 0
    if not a_pre:
        return 1
    if not b_pre:
        return -1

    a_key = _prerelease_key(a_pre)
    b_key = _prerelease_key(b_pre)

    for x, y in zip(a_key, b_key):
        if x < y:
            return -1
        if x > y:
            return 1

    if len(a_pre) < len(b_pre):
        return -1
    if len(a_pre) > len(b_pre):
        return 1

    return 0


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=lambda v: (parse_version(v), v))
