def parse_ini(text: str) -> dict:
    result: dict = {}
    current_section = ''
    current_key = None

    lines = text.split('\n')
    for i, raw_line in enumerate(lines, start=1):
        if raw_line.endswith('\r'):
            line = raw_line[:-1]
        else:
            line = raw_line

        if line.strip() == '':
            continue

        stripped = line.lstrip()
        first_non_ws = stripped[0]
        if first_non_ws in ';#':
            continue

        if line[0] in ' \t':
            if current_key is None:
                raise ValueError(f'line {i}: continuation without a key')
            section_dict = result.setdefault(current_section, {})
            current_value = section_dict[current_key]
            appended = line.strip()
            if current_value == '':
                section_dict[current_key] = appended
            else:
                section_dict[current_key] = current_value + ' ' + appended
            continue

        line_stripped = line.strip()
        if line_stripped.startswith('[') and line_stripped.endswith(']'):
            name = line_stripped[1:-1].strip().lower()
            result.setdefault(name, {})
            current_section = name
            current_key = None
            continue

        if '=' not in line:
            raise ValueError(f'line {i}: missing =')
        key_part, value_part = line.split('=', 1)
        key = key_part.strip().lower()
        if key == '':
            raise ValueError(f'line {i}: empty key')
        section_dict = result.setdefault(current_section, {})
        if key in section_dict:
            raise ValueError(f'duplicate key {key!r} in section {current_section!r}')
        section_dict[key] = value_part.strip()
        current_key = key

    for section in result.values():
        for key, value in section.items():
            if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
                section[key] = value[1:-1]

    return result
