def _parse_version(version: str) -> tuple[int, ...]:
    stripped = version.strip()
    if not stripped:
        raise ValueError("empty version")
    parts = stripped.split(".")
    if not parts:
        raise ValueError("empty version")
    parsed = []
    for part in parts:
        if not part:
            raise ValueError("empty version component")
        # Reject leading zeros? The spec says non-negative integers.
        # '01' is technically a valid non-negative integer, but semver-like
        # parsers often reject it. The plan says "non-negative integers",
        # so we allow it as int. However, we must reject anything else.
        try:
            num = int(part)
        except ValueError:
            raise ValueError(f"invalid version component: {part}")
        if num < 0:
            raise ValueError(f"negative version component: {part}")
        parsed.append(num)
    return tuple(parsed)


def _compare_versions(a: tuple[int, ...], b: tuple[int, ...]) -> int:
    max_len = max(len(a), len(b))
    for i in range(max_len):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av < bv:
            return -1
        if av > bv:
            return 1
    return 0


def _expand_tilde(version: tuple[int, ...]) -> tuple[tuple[int, ...], tuple[int, ...]]:
    if len(version) < 2:
        raise ValueError("~= requires a version with at least two components")
    lower = version
    upper_prefix = version[:-1]
    upper_last = upper_prefix[-1] + 1
    upper = upper_prefix[:-1] + (upper_last,)
    return lower, upper


def _parse_spec(spec: str) -> list[tuple[str, tuple[int, ...]]]:
    stripped = spec.strip()
    if not stripped:
        return []
    clauses = []
    for raw_clause in stripped.split(","):
        clause = raw_clause.strip()
        if not clause:
            raise ValueError("empty clause in spec")
        # Determine operator
        if clause.startswith("=="):
            op = "=="
            rest = clause[2:].strip()
        elif clause.startswith("!="):
            op = "!="
            rest = clause[2:].strip()
        elif clause.startswith(">="):
            op = ">="
            rest = clause[2:].strip()
        elif clause.startswith("<="):
            op = "<="
            rest = clause[2:].strip()
        elif clause.startswith(">"):
            op = ">"
            rest = clause[1:].strip()
        elif clause.startswith("<"):
            op = "<"
            rest = clause[1:].strip()
        elif clause.startswith("~="):
            op = "~="
            rest = clause[2:].strip()
        else:
            raise ValueError(f"missing operator in clause: {clause}")
        version = _parse_version(rest)
        clauses.append((op, version))
    return clauses


def _evaluate_clause(version: tuple[int, ...], op: str, target: tuple[int, ...]) -> bool:
    cmp = _compare_versions(version, target)
    if op == "==":
        return cmp == 0
    if op == "!=":
        return cmp != 0
    if op == ">=":
        return cmp >= 0
    if op == "<=":
        return cmp <= 0
    if op == ">":
        return cmp > 0
    if op == "<":
        return cmp < 0
    if op == "~=":
        lower, upper = _expand_tilde(target)
        return _compare_versions(version, lower) >= 0 and _compare_versions(version, upper) < 0
    raise ValueError(f"unknown operator: {op}")


def satisfies(version: str, spec: str) -> bool:
    parsed_version = _parse_version(version)
    clauses = _parse_spec(spec)
    for op, target in clauses:
        if not _evaluate_clause(parsed_version, op, target):
            return False
    return True


def max_satisfying(versions: list[str], spec: str) -> str | None:
    clauses = _parse_spec(spec)
    best_original = None
    best_parsed = None
    for original in versions:
        parsed = _parse_version(original)
        if not all(_evaluate_clause(parsed, op, target) for op, target in clauses):
            continue
        if best_parsed is None or _compare_versions(parsed, best_parsed) > 0:
            best_parsed = parsed
            best_original = original
    return best_original
