from decimal import Decimal, ROUND_HALF_EVEN
import re


class FifoBook:
    _PRICE_RE = re.compile(r'^[0-9]+(\.[0-9]{1,4})?$')

    def __init__(self):
        self._lots = deque()
        self._holdings = 0
        self._realized = Decimal('0.00')

    @staticmethod
    def _validate_qty(qty):
        if type(qty) is not int:
            raise TypeError('qty must be int')
        if qty <= 0:
            raise ValueError('qty must be positive')

    @staticmethod
    def _validate_price(price):
        if type(price) is not str:
            raise TypeError('price must be str')
        if not FifoBook._PRICE_RE.match(price):
            raise ValueError('invalid price format')

    def buy(self, qty: int, price: str) -> None:
        self._validate_qty(qty)
        self._validate_price(price)
        buy_price = Decimal(price)
        self._lots.append([qty, price, buy_price])
        self._holdings += qty

    def sell(self, qty: int, price: str) -> Decimal:
        self._validate_qty(qty)
        self._validate_price(price)
        if qty > self._holdings:
            raise ValueError('insufficient holdings')

        sell_price = Decimal(price)
        remaining = qty
        exact_pnl = Decimal('0')

        while remaining > 0:
            lot = self._lots[0]
            lot_qty, _, lot_buy_price = lot
            matched = lot_qty if lot_qty <= remaining else remaining
            exact_pnl += (sell_price - lot_buy_price) * matched
            lot[0] -= matched
            remaining -= matched
            self._holdings -= matched
            if lot[0] == 0:
                self._lots.popleft()

        quantized_pnl = exact_pnl.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
        self._realized += quantized_pnl
        return quantized_pnl

    def realized(self) -> Decimal:
        return self._realized

    def holdings(self) -> int:
        return self._holdings

    def lots(self) -> list[tuple[int, str]]:
        return [(lot[0], lot[1]) for lot in self._lots]

    def cost_basis(self) -> Decimal:
        exact = sum((Decimal(lot[1]) * lot[0] for lot in self._lots), Decimal('0'))
        return exact.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
