import copy


def _decode_pointer(pointer):
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("Non-empty pointer must start with '/'")
    raw_tokens = pointer[1:].split("/")
    decoded = []
    for raw in raw_tokens:
        chars = []
        i = 0
        while i < len(raw):
            ch = raw[i]
            if ch == "~":
                if i + 1 >= len(raw):
                    raise ValueError("Trailing '~' in pointer token")
                nxt = raw[i + 1]
                if nxt == "0":
                    chars.append("~")
                    i += 2
                elif nxt == "1":
                    chars.append("/")
                    i += 2
                else:
                    raise ValueError("Invalid escape sequence in pointer token")
            else:
                chars.append(ch)
                i += 1
        decoded.append("".join(chars))
    return decoded


def _parse_list_index(token, length, allow_append=False):
    if token == "-":
        if allow_append:
            return length
        raise KeyError("List index '-' not allowed in resolve")
    if token == "0":
        return 0
    if not token.isdigit():
        raise KeyError(f"Invalid list index: {token!r}")
    if token[0] == "0":
        raise KeyError(f"List index with leading zeros: {token!r}")
    idx = int(token)
    if idx < 0 or idx >= length:
        raise KeyError(f"List index out of range: {token!r}")
    return idx


def resolve(doc, pointer):
    tokens = _decode_pointer(pointer)
    value = doc
    for token in tokens:
        if isinstance(value, dict):
            if token not in value:
                raise KeyError(f"Missing key: {token!r}")
            value = value[token]
        elif isinstance(value, list):
            idx = _parse_list_index(token, len(value))
            value = value[idx]
        else:
            raise KeyError(f"Cannot step into non-container value at token: {token!r}")
    return value


def set_value(doc, pointer, value):
    tokens = _decode_pointer(pointer)
    if not tokens:
        return copy.deepcopy(value)
    new_doc = copy.deepcopy(doc)
    parent = new_doc
    for token in tokens[:-1]:
        if isinstance(parent, dict):
            if token not in parent:
                raise KeyError(f"Missing key: {token!r}")
            parent = parent[token]
        elif isinstance(parent, list):
            idx = _parse_list_index(token, len(parent))
            parent = parent[idx]
        else:
            raise KeyError(f"Cannot step into non-container value at token: {token!r}")
    last = tokens[-1]
    if isinstance(parent, dict):
        parent[last] = copy.deepcopy(value)
    elif isinstance(parent, list):
        if last == "-":
            parent.append(copy.deepcopy(value))
        elif last.isdigit() and (last == "0" or last[0] != "0"):
            idx = int(last)
            if idx == len(parent):
                parent.append(copy.deepcopy(value))
            elif 0 <= idx < len(parent):
                parent[idx] = copy.deepcopy(value)
            else:
                raise KeyError(f"List index out of range: {last!r}")
        else:
            raise KeyError(f"Invalid list index for set_value: {last!r}")
    else:
        raise KeyError(f"Parent is not a dict or list: {last!r}")
    return new_doc


def escape_token(token):
    return token.replace("~", "~0").replace("/", "~1")


def _test():
    doc = {
        "": 0,
        "a/b": 1,
        "c%d": 2,
        "e^f": 3,
        "g|h": 4,
        "i\\j": 5,
        'k"l': 6,
        " ": 7,
        "m~n": 8,
        "foo": ["bar", "baz"],
        "qux": {"answer": 42},
        "list": [1, 2, 3],
    }

    assert resolve(doc, "") is doc
    assert resolve(doc, "/") == 0
    assert resolve(doc, "/a~1b") == 1
    assert resolve(doc, "/m~0n") == 8
    assert resolve(doc, "/foo/0") == "bar"
    assert resolve(doc, "/foo/1") == "baz"
    assert resolve(doc, "/qux/answer") == 42

    try:
        resolve(doc, "bad")
        assert False
    except ValueError:
        pass

    try:
        resolve(doc, "/m~")
        assert False
    except ValueError:
        pass

    try:
        resolve(doc, "/m~2n")
        assert False
    except ValueError:
        pass

    try:
        resolve(doc, "/foo/-")
        assert False
    except KeyError:
        pass

    try:
        resolve(doc, "/foo/00")
        assert False
    except KeyError:
        pass

    try:
        resolve(doc, "/foo/01")
        assert False
    except KeyError:
        pass

    try:
        resolve(doc, "/foo/3")
        assert False
    except KeyError:
        pass

    try:
        resolve(doc, "/foo/bar")
        assert False
    except KeyError:
        pass

    try:
        resolve(doc, "/qux/answer/extra")
        assert False
    except KeyError:
        pass

    assert escape_token("a/b") == "a~1b"
    assert escape_token("m~n") == "m~0n"
    assert escape_token("~01") == "~001"

    new_doc = set_value(doc, "/qux/answer", 100)
    assert new_doc["qux"]["answer"] == 100
    assert doc["qux"]["answer"] == 42

    new_doc2 = set_value(doc, "/list/-", 4)
    assert new_doc2["list"] == [1, 2, 3, 4]
    assert doc["list"] == [1, 2, 3]

    new_doc3 = set_value(doc, "/list/3", 4)
    assert new_doc3["list"] == [1, 2, 3, 4]

    new_doc4 = set_value(doc, "/list/1", 99)
    assert new_doc4["list"] == [1, 99, 3]

    new_doc5 = set_value(doc, "", {"replaced": True})
    assert new_doc5 == {"replaced": True}

    new_doc6 = set_value(doc, "/new", {"nested": [1, 2]})
    assert new_doc6["new"] == {"nested": [1, 2]}

    try:
        set_value(doc, "/missing/key", 1)
        assert False
    except KeyError:
        pass

    try:
        set_value(doc, "/list/5", 1)
        assert False
    except KeyError:
        pass

    try:
        set_value(doc, "/list/01", 1)
        assert False
    except KeyError:
        pass

    try:
        set_value(doc, "/qux/answer/extra", 1)
        assert False
    except KeyError:
        pass

    nested = {"a": {"b": [1, 2]}}
    new_nested = set_value(nested, "/a/b/-", 3)
    assert new_nested == {"a": {"b": [1, 2, 3]}}
    assert nested == {"a": {"b": [1, 2]}}

    print("All tests passed.")


if __name__ == "__main__":
    _test()
