    result: list[str] = []
    current: str = ""

    for word in words:
        if len(word) > width:
            if current:
                result.append(current)
                current = ""

            while len(word) > width:
                chunk = word[:width - 1] + "-"
                result.append(chunk)
                word = word[width - 1:]

            current = word
            continue

        if current:
            candidate = current + " " + word
        else:
            candidate = word

        if len(candidate) <= width:
            current = candidate
        else:
            if current:
                result.append(current)
            current = word

    if current:
        result.append(current)

    return result
