def validate_stream(events):
    seen_ids = set()
    for event in events:
        event_id = event[1]
        if event_id in seen_ids:
            raise ValueError(f'duplicate id {event_id}')
        seen_ids.add(event_id)

    prev = None
    for event in events:
        key = (event[0], event[1])
        if prev is not None and key <= prev:
            raise ValueError(f'unsorted at {event[1]}')
        prev = key

    return None


def diff_events(old, new):
    validate_stream(old)
    validate_stream(new)

    old_map = {event[1]: event for event in old}
    new_map = {event[1]: event for event in new}

    old_ids = set(old_map)
    new_ids = set(new_map)

    added = [event_id for event_id in (event[1] for event in new) if event_id in new_ids - old_ids]
    removed = [event_id for event_id in (event[1] for event in old) if event_id in old_ids - new_ids]
    moved = []
    changed = []
    seen_shared = set()
    for event in new:
        event_id = event[1]
        if event_id in old_ids and event_id not in seen_shared:
            seen_shared.add(event_id)
            old_event = old_map[event_id]
            if event[0] != old_event[0]:
                moved.append(event_id)
            if event[2] != old_event[2]:
                changed.append(event_id)

    return {
        'added': added,
        'removed': removed,
        'moved': moved,
        'changed': changed,
    }


def merge_streams(a, b):
    validate_stream(a)
    validate_stream(b)

    b_ids = {event[1] for event in b}
    filtered_a = [event for event in a if event[1] not in b_ids]

    merged = []
    i = j = 0
    while i < len(filtered_a) and j < len(b):
        a_key = (filtered_a[i][0], filtered_a[i][1])
        b_key = (b[j][0], b[j][1])
        if a_key < b_key:
            merged.append(filtered_a[i])
            i += 1
        else:
            merged.append(b[j])
            j += 1

    merged.extend(filtered_a[i:])
    merged.extend(b[j:])

    return merged
